import random
from collections import deque

def has_short_cycle(adj, u, v, min_girth=7):
    """Check if adding edge (u,v) creates a cycle of length < min_girth"""
    # BFS from u to v without using edge (u,v)
    # If shortest path from u to v has length <= min_girth - 2, adding edge creates short cycle
    dist = {u: 0}
    queue = deque([u])
    while queue:
        node = queue.popleft()
        if dist[node] >= min_girth - 2:
            continue
        for neighbor in adj[node]:
            if neighbor == v:
                return True
            if neighbor not in dist:
                dist[neighbor] = dist[node] + 1
                queue.append(neighbor)
    return False

def try_build_graph(n=20, min_girth=7, seed=42):
    random.seed(seed)
    adj = [set() for _ in range(n)]
    edges = []

    all_possible = [(i,j) for i in range(n) for j in range(i+1,n)]
    random.shuffle(all_possible)

    for u, v in all_possible:
        if not has_short_cycle(adj, u, v, min_girth):
            adj[u].add(v)
            adj[v].add(u)
            edges.append((u,v))

    return edges, adj

best_edges = []
best_adj = None
for seed in range(200):
    edges, adj = try_build_graph(seed=seed)
    if len(edges) > len(best_edges):
        best_edges = edges
        best_adj = [set(s) for s in adj]
        print(f"Seed {seed}: {len(edges)} edges")

print(f"\nBest found: {len(best_edges)} edges")
